import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"5、【需】 乾下坎上","description":"温公易说 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"温公易说 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"zh/classics/wengong/006.md","filePath":"zh/classics/wengong/006.md"}'),t={name:"zh/classics/wengong/006.md"};function n(l,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><h3 id="彖曰-需须也-险在前也。刚健而不陷-其义不困穷矣。需有孚光亨贞吉-位乎天位以正中也。利涉大川-往有功也。" tabindex="-1">彖曰：需须也，险在前也。刚健而不陷，其义不困穷矣。需有孚光亨贞吉，位乎天位以正中也。利涉大川，往有功也。 <a class="header-anchor" href="#彖曰-需须也-险在前也。刚健而不陷-其义不困穷矣。需有孚光亨贞吉-位乎天位以正中也。利涉大川-往有功也。" aria-label="Permalink to “彖曰：需须也，险在前也。刚健而不陷，其义不困穷矣。需有孚光亨贞吉，位乎天位以正中也。利涉大川，往有功也。”">​</a></h3><p>坎陷也，其云不陷何需然后进，故不陷也。又曰位乎天位以正中者，何有孚光亨贞吉者，人君所以待天下之道也。</p><h3 id="象曰-云上于天-需。君子以饮食宴乐。" tabindex="-1">象曰：云上于天，需。君子以饮食宴乐。 <a class="header-anchor" href="#象曰-云上于天-需。君子以饮食宴乐。" aria-label="Permalink to “象曰：云上于天，需。君子以饮食宴乐。”">​</a></h3><p>需之为饮食何也？云上于天，万物之滂沱下施，万物饮之以丰以肥以荣以滋，饮食燕乐及下之道也。</p><h3 id="初九-需于郊-利用恒-无咎。-象曰-需于郊-不犯难行也。利用恒-无咎-未失常也。" tabindex="-1">初九：需于郊，利用恒，无咎。 象曰：需于郊，不犯难行也。利用恒，无咎，未失常也。 <a class="header-anchor" href="#初九-需于郊-利用恒-无咎。-象曰-需于郊-不犯难行也。利用恒-无咎-未失常也。" aria-label="Permalink to “初九：需于郊，利用恒，无咎。 象曰：需于郊，不犯难行也。利用恒，无咎，未失常也。”">​</a></h3><h3 id="九二-需于沙-小有言-终吉。-象曰-需于沙-衍在中也。虽小有言-以吉终也。" tabindex="-1">九二：需于沙，小有言，终吉。 象曰：需于沙，衍在中也。虽小有言，以吉终也。 <a class="header-anchor" href="#九二-需于沙-小有言-终吉。-象曰-需于沙-衍在中也。虽小有言-以吉终也。" aria-label="Permalink to “九二：需于沙，小有言，终吉。 象曰：需于沙，衍在中也。虽小有言，以吉终也。”">​</a></h3><h3 id="九三-需于泥-致寇至。-象曰-需于泥-灾在外也。自我致寇-敬慎不败也。" tabindex="-1">九三：需于泥，致寇至。 象曰：需于泥，灾在外也。自我致寇，敬慎不败也。 <a class="header-anchor" href="#九三-需于泥-致寇至。-象曰-需于泥-灾在外也。自我致寇-敬慎不败也。" aria-label="Permalink to “九三：需于泥，致寇至。 象曰：需于泥，灾在外也。自我致寇，敬慎不败也。”">​</a></h3><p>寇虽迩，不犯，不至，故曰自我致之，能用需道，故曰敬慎不败也。</p><h3 id="六四-需于血-出自穴。-象曰-需于血-顺以听也。" tabindex="-1">六四：需于血，出自穴。 象曰：需于血，顺以听也。 <a class="header-anchor" href="#六四-需于血-出自穴。-象曰-需于血-顺以听也。" aria-label="Permalink to “六四：需于血，出自穴。 象曰：需于血，顺以听也。”">​</a></h3><p>需于血者，入险而伤也。出于险者，不竞乃善也。以需血者，非需之地也。子曰：&quot;繋辞焉以尽其言，变而通之以尽利，此之谓也。&quot;</p><h3 id="九五-需于酒食-贞吉。-象曰-酒食贞吉-以中正也。" tabindex="-1">九五：需于酒食，贞吉。 象曰：酒食贞吉，以中正也。 <a class="header-anchor" href="#九五-需于酒食-贞吉。-象曰-酒食贞吉-以中正也。" aria-label="Permalink to “九五：需于酒食，贞吉。 象曰：酒食贞吉，以中正也。”">​</a></h3><p>需九五需于酒食贞吉，酒食者，福禄之谓也。</p><h3 id="上六-入于穴-有不速之客三人来-敬之终吉。-象曰-不速之客来-敬之终吉。虽不当位-未大失也。" tabindex="-1">上六：入于穴，有不速之客三人来，敬之终吉。 象曰：不速之客来，敬之终吉。虽不当位，未大失也。 <a class="header-anchor" href="#上六-入于穴-有不速之客三人来-敬之终吉。-象曰-不速之客来-敬之终吉。虽不当位-未大失也。" aria-label="Permalink to “上六：入于穴，有不速之客三人来，敬之终吉。 象曰：不速之客来，敬之终吉。虽不当位，未大失也。”">​</a></h3>',14)])])}const b=e(t,[["render",n]]);export{p as __pageData,b as default};
